import { Audio } from "expo-av";
import * as Speech from "expo-speech";

export type AudioAssetMap = Record<string, number>;

let activeSound: Audio.Sound | null = null;
let cachedMaleVoiceId: string | null | undefined = undefined;
let audioModeConfigured = false;
let audioAssetsCache: AudioAssetMap | null = null;

function getAudioAssets(): AudioAssetMap {
  if (audioAssetsCache) return audioAssetsCache;
  try {
    // Generated by scripts/generate_audio_assets.py using erkamk/yazgi-tts-1 (male-01)
    const mod = require("./audioAssets");
    audioAssetsCache = mod.AUDIO_ASSETS || {};
  } catch {
    audioAssetsCache = {};
  }
  return audioAssetsCache!;
}

async function ensureAudioMode(): Promise<void> {
  if (audioModeConfigured) return;
  try {
    await Audio.setAudioModeAsync({
      playsInSilentModeIOS: true,
      allowsRecordingIOS: false,
      staysActiveInBackground: false,
      shouldDuckAndroid: true,
    });
    audioModeConfigured = true;
  } catch {
    // ignore on web or unsupported environment
  }
}

async function resolveTurkishMaleVoiceId(): Promise<string | undefined> {
  if (cachedMaleVoiceId !== undefined) {
    return cachedMaleVoiceId ?? undefined;
  }
  try {
    const voices = await Speech.getAvailableVoicesAsync();
    const trVoices = voices.filter((v) =>
      (v.language || "").toLowerCase().startsWith("tr")
    );

    const maleHints = ["cem", "kerem", "ahmet", "tolga", "emre", "mehmet", "male", "erkek"];
    const femaleHints = ["yelda", "seda", "ayse", "derya", "filiz", "female", "kadin"];

    const explicitMale = trVoices.find((v) => {
      const hay = `${v.identifier || ""} ${v.name || ""}`.toLowerCase();
      return maleHints.some((h) => hay.includes(h));
    });
    if (explicitMale) {
      cachedMaleVoiceId = explicitMale.identifier;
      return explicitMale.identifier;
    }

    const nonFemale = trVoices.find((v) => {
      const hay = `${v.identifier || ""} ${v.name || ""}`.toLowerCase();
      return !femaleHints.some((h) => hay.includes(h));
    });
    cachedMaleVoiceId = nonFemale?.identifier ?? null;
    return cachedMaleVoiceId ?? undefined;
  } catch {
    cachedMaleVoiceId = null;
    return undefined;
  }
}

export async function stopNarration(): Promise<void> {
  if (activeSound) {
    const soundToUnload = activeSound;
    activeSound = null;
    try {
      soundToUnload.setOnPlaybackStatusUpdate(null);
      await soundToUnload.stopAsync();
      await soundToUnload.unloadAsync();
    } catch {
      // ignore cleanup errors
    }
  }
  try {
    Speech.stop();
  } catch {
    // ignore
  }
}

export interface PlayNarrationOptions {
  clipId?: string;
  fallbackText: string;
  onFinish?: () => void;
  onError?: () => void;
}

/**
 * Plays natural Turkish male storytelling narration powered by erkamk/yazgi-tts-1 (male-01),
 * with automatic male-voice fallback via system speech synthesis if a dynamic/custom clip is requested.
 */
export async function playNarration({
  clipId,
  fallbackText,
  onFinish,
  onError,
}: PlayNarrationOptions): Promise<void> {
  await stopNarration();

  const assets = getAudioAssets();
  const assetSource = clipId ? assets[clipId] : undefined;

  if (assetSource) {
    try {
      await ensureAudioMode();
      const { sound } = await Audio.Sound.createAsync(
        assetSource,
        { shouldPlay: true, volume: 1.0 },
        (status) => {
          if (status.isLoaded && status.didJustFinish) {
            if (activeSound === sound) {
              activeSound = null;
            }
            sound.setOnPlaybackStatusUpdate(null);
            sound.unloadAsync().catch(() => {});
            onFinish?.();
          }
        }
      );
      activeSound = sound;
      return;
    } catch {
      // Fall through to male TTS fallback below
    }
  }

  try {
    const maleVoiceId = await resolveTurkishMaleVoiceId();
    Speech.speak(fallbackText, {
      language: "tr-TR",
      voice: maleVoiceId,
      rate: 0.94,
      pitch: maleVoiceId ? 0.96 : 0.85,
      onDone: () => onFinish?.(),
      onStopped: () => onFinish?.(),
      onError: () => onError?.(),
    });
  } catch {
    onError?.();
  }
}
